import { after, before, test } from 'node:test'
import { TwilioStudio } from "twilio-studio-sdk"
import { mock } from '../mock/server.mjs'

let server
let client

before(async () => {
  server = await mock()
  client = new TwilioStudio({ baseURL: server.url, accountSidAuthToken: { username: 'user', password: 'pass' }, maxRetries: 0 })
})

after(() => server.close())

/** The request the mock answered last; `null` against a server of your own. */
const last = () => server.requests?.at(-1) ?? null

test("accountSid_authToken: sent by flows.list", async () => {
  await client.flows.list()
  const r = last()
  if (r === null) return
  assert.equal(r.headers.authorization, `Basic ${Buffer.from('user:pass').toString('base64')}`)
})
